#!/bin/sh
# Autogenerated test: runs inside a container built from each compatibility image with act installed with default
# options (version latest, defaultImage none). POSIX sh, because alpine:3.24 ships no bash.
set -eu

# The path is computed from $0 at run time, so shellcheck cannot follow it.
# shellcheck source=/dev/null
. "$(dirname "$0")/checks.sh"

# Computed at run time: the default option installs whatever release the latest-release link names.
latest="$(latest_release)"

# Before act runs at all: act creates ~/.config/act on its first run, so it cannot pass as written by the install.
check "neither the remote user's nor root's home holds .actrc, .config/act, or .cache/act" no_act_files_in_homes

no_other_act_variables() {
  no_other_act_variables_set="$(env | grep '^ACT_' | grep -v '^ACT_DISABLE_VERSION_CHECK=' || true)"
  if [ -n "${no_other_act_variables_set}" ]; then
    printf '  set: %s\n' "${no_other_act_variables_set}"
    return 1
  fi
}
check "no environment variable starting with ACT_ other than ACT_DISABLE_VERSION_CHECK is set" no_other_act_variables
check "ACT_DISABLE_VERSION_CHECK is 1" test "${ACT_DISABLE_VERSION_CHECK-}" = "1"

no_docker_installed() {
  for no_docker_command in docker dockerd; do
    if command -v "${no_docker_command}" >/dev/null 2>&1; then
      printf '  %s resolves to %s\n' "${no_docker_command}" "$(command -v "${no_docker_command}")"
      return 1
    fi
  done
}
check "neither docker nor dockerd resolves on PATH" no_docker_installed

check "command -v act resolves to /usr/local/bin/act" act_resolves_to_usr_local_bin
check "act --version exits 0" act --version
check "act --version reports the release the latest-release link points to" act_reports_version "${latest}"

# The listing parses the workflow without a Docker Engine; the job id is the assertion, the table layout is not.
list_names_the_job() {
  list_dir="$(make_workflow_dir)" || return 1
  list_output="$(cd "${list_dir}" && act --list 2>&1)" || {
    printf '%s\n' "${list_output}"
    return 1
  }
  printf '%s\n' "${list_output}" | grep -q 'hello' || {
    printf '%s\n' "${list_output}"
    return 1
  }
}
check "act --list exits 0 and names the workflow's job without a Docker Engine" list_names_the_job

# No file under apt's package lists, dnf's cache, or apk's cache, whichever of them the image has.
package_caches_empty() {
  for package_caches_empty_dir in /var/lib/apt/lists /var/cache/libdnf5 /var/cache/apk; do
    if [ ! -d "${package_caches_empty_dir}" ]; then continue; fi
    package_caches_empty_files="$(as_root find "${package_caches_empty_dir}" -type f)" || return 1
    if [ -n "${package_caches_empty_files}" ]; then
      printf '  files remain under %s:\n%s\n' "${package_caches_empty_dir}" "${package_caches_empty_files}"
      return 1
    fi
  done
}
check "apt's package lists, dnf's cache, and apk's cache hold no file" package_caches_empty
check "no temporary directory or staged file of the install remains" no_install_leftovers

reportResults
